"use client";
import { ShaderSurface, type ShaderSurfaceOptions } from "./shader-surface";
export interface DitherCursorTrailProps
  extends Pick<
    ShaderSurfaceOptions,
    | "children"
    | "className"
    | "style"
    | "height"
    | "background"
    | "radius"
    | "duration"
    | "intensity"
    | "maxDpr"
    | "onReady"
  > {
  color?: string;
  dotSize?: number;
}
/** Pointer marks decay through ordered dot thresholds. Decorative trails stop on touch/reduced motion. */
export function DitherCursorTrail({
  color = "#161616",
  dotSize = 5,
  ...props
}: DitherCursorTrailProps) {
  return (
    <ShaderSurface
      kind="trail"
      radius={65}
      duration={2}
      scale={dotSize}
      colors={[color]}
      {...props}
    />
  );
}
